#include<bits/stdc++.h>

#define MSTSZ 262144

using namespace std;

vector<long long> merge(vector<long long> l,vector<long long> r){
  vector<long long> res;
  long long lp=0,rp=0;
  while(lp<l.size() || rp<r.size()){
    if(lp==l.size()){res.push_back(r[rp]);rp++;}
    else if(rp==r.size()){res.push_back(l[lp]);lp++;}
    else if(l[lp]<r[rp]){res.push_back(l[lp]);lp++;}
    else{res.push_back(r[rp]);rp++;}
  }
  return res;
}

long long soll,solr;
long long solx;

long long solve(
  long long l,long long r,long long id,
  vector<vector<long long>> &mst,vector<vector<long long>> &sum){
  if(l>=r){return 0;}
  if(solr<l){return 0;}
  if((r-1)<soll){return 0;}

  if(soll<=l && (r-1)<=solr){
    long long nl=0,nr=mst[id].size()-1;
    while(nl<=nr){
      long long te=(nl+nr)/2;
      if(mst[id][te]<=solx){nl=te+1;}
      else{nr=te-1;}
    }
    if(nr>=0){return sum[id][nr];}
    return 0;
  }

  long long up=0;
  up+=solve(l,(l+r)/2,2*id+1,mst,sum);
  up+=solve((l+r)/2,r,2*id+2,mst,sum);
  return up;
}

int main(){
  int n;
  cin >> n;
  vector<long long> a(n);
  for(auto &nx : a){cin >> nx;}
  long long big=2e9;
  while(a.size()<MSTSZ){a.push_back(big);}

  vector<vector<long long>> mst(2*MSTSZ);

  for(int i=0;i<MSTSZ;i++){
    mst[(MSTSZ-1)+i].push_back(a[i]);
  }
  for(int i=MSTSZ-2;i>=0;i--){
    mst[i]=merge(mst[2*i+1],mst[2*i+2]);
  }

  vector<vector<long long>> sum=mst;
  for(auto &nx : sum){
    int l=nx.size();
    for(int i=1;i<l;i++){
      nx[i]+=nx[i-1];
    }
  }

  int q;
  cin >> q;
  long long b=0;
  vector<long long> res;
  while(q>0){
    q--;
    long long alp,bet,gam;
    cin >> alp >> bet >> gam;

    long long l=(alp^b);
    long long r=(bet^b);
    long long x=(gam^b);

    soll=l-1;
    solr=r-1;
    solx=x;

    b=solve(0,MSTSZ,0,mst,sum);
    res.push_back(b);
  }

  for(auto &nx : res){
    cout << nx << "\n";
  }
  return 0;
}

use itertools::izip;
use proconio::input;

fn main() {
    input! {
        n: usize,
        mut a: [usize; n],
        q: usize,
        queries: [(usize, usize, usize); q],
    }
    let lg = (a.iter().copied().max().unwrap() + 2)
        .next_power_of_two()
        .trailing_zeros() as usize;
    let mut cums = Vec::new();
    let mut ranks = Vec::new();
    for i in (0..lg).rev() {
        // ランクを計算
        let mut rank = vec![0; n + 1];
        for (j, &x) in a.iter().enumerate() {
            rank[j + 1] = rank[j] + ((x >> i) & 1);
        }
        // a を第 i ビットをキーに逆順ソート
        let mut swp = vec![usize::MAX; n];
        for (j, &x) in a.iter().enumerate() {
            swp[match (x >> i) & 1 {
                0 => rank[n] + j - rank[j],
                1 => rank[j],
                _ => unreachable!(),
            }] = a[j];
        }
        // a の累積和を計算
        a = swp;
        let mut cum = vec![0; n + 1];
        for (j, &x) in a.iter().enumerate() {
            cum[j + 1] = cum[j] + x;
        }
        ranks.push(rank);
        cums.push(cum);
    }
    let mut rng = 0;
    for (alpha, beta, gamma) in queries {
        let mut l = (alpha ^ rng) - 1;
        let mut r = beta ^ rng;
        let x = ((gamma ^ rng) + 1).min((1 << lg) - 1);
        let mut ans = 0;
        for (i, cum, rank) in izip!((0..lg).rev(), &cums, &ranks) {
            // (l, r) が次の段の前半・後半でどこに相当するかを計算
            let l1 = rank[l];
            let r1 = rank[r];
            let l0 = rank[n] + l - l1;
            let r0 = rank[n] + r - r1;
            (l, r) = match x >> i & 1 {
                0 => (l0, r0),
                1 => {
                    ans += cum[r0] - cum[l0];
                    (l1, r1)
                }
                _ => unreachable!(),
            };
        }
        println!("{ans}");
        rng = ans;
    }
}
